请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-010

=== 用户原始指令 (query.txt) ===
整个清理卡嘛 要个图 写一行数字 点了能打电话 能看日程 红色危险提示哈

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个清理卡嘛 要个图 写一行数字 点了能打电话 能看日程 红色危险提示哈",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToCallPhone",
      "args": {
        "phoneNumber": "10086"
      }
    }
  ],
  "dataModelSchema": {
    "memory": {
      "usageText": {
        "type": "string",
        "description": "内存清理卡主显示数字，表示当前内存占用比例。",
        "sampleValue": "86%"
      },
      "statusText": {
        "type": "string",
        "description": "红色危险状态短提示。",
        "sampleValue": "危险"
      }
    },
    "contact": {
      "phoneNumber": {
        "type": "string",
        "description": "点击拨号使用的电话号码样例。",
        "sampleValue": "10086"
      },
      "actionLabel": {
        "type": "string",
        "description": "拨号动作按钮文案。",
        "sampleValue": "拨打电话"
      }
    },
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "今日紧凑日程列表。",
          "sampleValue": [
            {
              "entityName": "calendar",
              "entityId": "calendar-demo-001",
              "title": "清理提醒",
              "dtStart": "14:30",
              "dtEnd": "15:00"
            }
          ],
          "items": {
            "type": "object",
            "description": "单条日程。",
            "properties": {
              "entityName": {
                "type": "string",
                "description": "日程实体类别。",
                "sampleValue": "calendar"
              },
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符。",
                "sampleValue": "calendar-demo-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题。",
                "sampleValue": "清理提醒"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间。",
                "sampleValue": "14:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间。",
                "sampleValue": "15:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/clean_fill.svg",
      "description": "清洁实心图标，适合表达内存清理或清理动作。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合表达今日日程或日程查看。"
    }
  ]
}

